\[
\boxed{\text{The ferromagnetic ground state breaks }O(3)\text{ to }O(2).
\text{ Its two broken generators form one quadratic Goldstone mode, so }n_{FM}=1.
\text{ The noncollinear antiferromagnetic ground state breaks }O(3)\text{ completely and has zero net magnetization, yielding three Goldstone modes. Thus }\;
n_{FM}=1\;;\;n_{AF}=3.}
\]
